//! State-preserving moves publish native topology without removal/insertion lifecycle.
use super::*;
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str)->Value{p.begin_job();p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap()}
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document("<!doctype html><html><body><div>Main</div></body></html>",&||Ok(())).unwrap();d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();p.set_location(&crate::navigation::address("https://move.test/source",&crate::navigation::Location::home()).unwrap());assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}

#[test]
fn state_preserving_move_canonical_parent_mixin_and_binding_checks(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
for(var proto of [Element.prototype,Document.prototype,DocumentFragment.prototype]){var d=Object.getOwnPropertyDescriptor(proto,'moveBefore');if(!d||typeof d.value!=='function'||d.value.name!=='moveBefore'||d.value.length!==2||!d.enumerable||!d.configurable||!d.writable||Object.hasOwn(proto[Symbol.unscopables],'moveBefore'))throw 'canonical ParentNode moveBefore';}var m=Element.prototype.moveBefore,hits=0,arg={toString:function(){hits++;throw 'coercion';}},host=document.createElement('div'),node=document.createElement('b');host.appendChild(node);for(var args of [[],[node],[arg,null],[node,arg],[null,null],[{},null]]){var error;try{m.apply(host,args);}catch(e){error=e;}if(!(error instanceof TypeError))throw 'required Node and nullable Node bindings';}for(var bad of [{},window,node.firstChild,document.createTextNode('x'),document.createAttribute('x')]){var error;try{m.call(bad,arg,null);}catch(e){error=e;}if(!(error instanceof TypeError))throw 'genuine ParentNode brand';}if(hits)throw 'Node binding must not coerce';var error;try{new m();}catch(e){error=e;}if(!(error instanceof TypeError))throw 'not constructor';
"#);}

#[test]
fn state_preserving_move_native_records_ranges_iterators_and_self_reference(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
if(typeof Element.prototype.moveBefore!=='function')throw 'missing native moveBefore';for(var owner of [document,new Document(),document.createElement('template').content.ownerDocument]){var root=owner.createElement('div'),a=owner.createElement('div'),b=owner.createElement('div'),node=owner.createElement('b'),text=owner.createTextNode('abc'),tail=owner.createComment('tail');root.append(a,b);node.appendChild(text);a.appendChild(node);b.appendChild(tail);var list=a.childNodes,range=owner.createRange();range.setStart(text,1);range.setEnd(text,2);var iterator=owner.createNodeIterator(root,NodeFilter.SHOW_ALL);while(iterator.nextNode()!==text){}var watch=new MutationObserver(function(){});watch.observe(root,{childList:true,subtree:true});if(b.moveBefore(node,tail)!==undefined)throw 'undefined return';var records=watch.takeRecords();if(records.length!==2||records[0].target!==a||records[0].removedNodes[0]!==node||records[1].target!==b||records[1].addedNodes[0]!==node||records[1].nextSibling!==tail||list.length||node.parentNode!==b||node.firstChild!==text||range.startContainer!==a||range.startOffset!==0||iterator.referenceNode!==a)throw 'actual move records ranges iterator';b.moveBefore(node,node);records=watch.takeRecords();if(records.length!==2||records[0].removedNodes[0]!==node||records[1].addedNodes[0]!==node||b.firstChild!==node)throw 'self reference adjusts before native move';b.moveBefore(tail,undefined);if(watch.takeRecords().length!==2||b.lastChild!==tail)throw 'explicit undefined nullable reference and last move records';watch.disconnect();}
"#);}

#[test]
fn state_preserving_move_same_root_and_hierarchy_errors_preserve_actual_tree(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
if(typeof Element.prototype.moveBefore!=='function')throw 'missing native moveBefore';var root=document.createElement('div'),left=document.createElement('div'),right=document.createElement('div'),node=document.createTextNode('x'),other=document.createElement('i'),frag=document.createDocumentFragment();root.append(left,right);left.appendChild(node);var watch=new MutationObserver(function(){});watch.observe(root,{childList:true,subtree:true});for(var pair of [[right,other,null,'HierarchyRequestError'],[left,root,null,'HierarchyRequestError'],[right,node,other,'NotFoundError'],[right,frag,null,'HierarchyRequestError'],[right,document,null,'HierarchyRequestError']]){var error;try{pair[0].moveBefore(pair[1],pair[2]);}catch(e){error=e;}if(!(error instanceof DOMException)||error.name!==pair[3])throw 'typed move eligibility error';}if(node.parentNode!==left||left.parentNode!==root||right.parentNode!==root||watch.takeRecords().length)throw 'invalid moves atomic';right.moveBefore(node,null);if(node.parentNode!==right||watch.takeRecords().length!==2)throw 'eligibility recovery';
"#);}

#[test]
fn state_preserving_move_connected_frame_and_editor_identity_survive_native_move(){
 let(mut d,mut f,mut p)=fixture();let Value::Host(edit)=run(&mut d,&mut f,&mut p,r#"
if(typeof Element.prototype.moveBefore!=='function')throw 'missing native moveBefore';var left=document.createElement('div'),right=document.createElement('div'),node=document.createElement('section'),frame=document.createElement('iframe'),edit=document.createElement('input');frame.hidden=true;document.body.append(left,right);left.appendChild(node);node.appendChild(frame);left.appendChild(edit);edit.value='changed';var w=frame.contentWindow,doc=frame.contentDocument,body=doc.body;var ChildFunction=w.Function,marker=ChildFunction('window.moveMarker={kept:true};return window.moveMarker;')();edit;
"#)else{panic!("actual native editor missing")};let edit=node_index(edit).unwrap();let value=&mut f.controls.get_mut(&edit).unwrap().value;value.cursor=4;value.anchor=1;let editor=(value.text(),value.cursor,value.anchor,value.offset);
 run(&mut d,&mut f,&mut p,r#"right.moveBefore(node,null);right.moveBefore(edit,null);if(node.parentNode!==right||!node.isConnected||frame.contentWindow!==w||frame.contentDocument!==doc||doc.body!==body||ChildFunction('return window.moveMarker;')()!==marker||edit.value!=='changed')throw 'native browsing context and dirty editor preserved';"#);
 let value=&f.controls[&edit].value;assert_eq!((value.text(),value.cursor,value.anchor,value.offset),editor);
}

#[test]
fn state_preserving_move_saved_child_method_owner_refuses_and_recovers(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
if(typeof Element.prototype.moveBefore!=='function')throw 'missing native moveBefore';var frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var m=frame.contentWindow.Element.prototype.moveBefore,host=document.createElement('div'),a=document.createElement('b'),b=document.createElement('i');host.append(a,b);m.call(host,b,a);if(host.firstChild!==b)throw 'borrowed owner method';
"#);p.set_location(&crate::navigation::address("https://other.test/",&crate::navigation::Location::home()).unwrap());p.begin_job();let error=p.runtime.execute("m.call(host,a,null)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(error.contains("origin"),"{error}");p.set_location(&crate::navigation::address("https://move.test/source",&crate::navigation::Location::home()).unwrap());run(&mut d,&mut f,&mut p,"if(host.firstChild!==b)throw 'owner refusal changed tree';m.call(host,a,b);if(host.firstChild!==a)throw 'owner recovery';");}

#[test]
fn state_preserving_move_inert_document_validity_and_character_data_keep_real_identity(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
var owner=new Document(),root=owner.createElement('Root'),comment=owner.createComment('lead'),pi=owner.createProcessingInstruction('p','raw'),dtype=owner.implementation.createDocumentType('Root','','');owner.appendChild(dtype);owner.appendChild(comment);owner.appendChild(root);root.appendChild(pi);var watch=new MutationObserver(function(){});watch.observe(owner,{childList:true,subtree:true});owner.moveBefore(pi,comment);if(pi.parentNode!==owner||owner.childNodes[1]!==pi||pi.data!=='raw'||watch.takeRecords().length!==2)throw 'actual inert Document PI move';for(var pair of [[root,root],[dtype,null]]){var error;try{owner.moveBefore(pair[0],pair[1]);}catch(e){error=e;}if(!(error instanceof DOMException)||error.name!=='HierarchyRequestError')throw 'Document element and doctype move eligibility';}var text=owner.createTextNode('exact'+String.fromCharCode(55296));root.appendChild(text);var error;try{owner.moveBefore(text,null);}catch(e){error=e;}if(!(error instanceof DOMException)||error.name!=='HierarchyRequestError'||text.parentNode!==root)throw 'Document Text refusal';root.moveBefore(text,null);if(text.data.charCodeAt(5)!==55296||text.ownerDocument!==owner)throw 'raw UTF16 identity';
"#);}
#[test]
fn state_preserving_move_transient_source_observation_survives_until_real_delivery(){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,r#"
for(var owner of [document,new Document()]){var root=owner.createElement('div'),left=owner.createElement('div'),right=owner.createElement('div'),text=owner.createTextNode('old');root.append(left,right);left.appendChild(text);var watch=new MutationObserver(function(){});watch.observe(left,{childList:true,subtree:true,characterData:true,characterDataOldValue:true});right.moveBefore(text,null);text.data='new';var records=watch.takeRecords();if(records.length!==2||records[0].target!==left||records[0].removedNodes[0]!==text||records[1].target!==text||records[1].oldValue!=='old'||text.parentNode!==right)throw 'real source transient observation';watch.disconnect();}
"#);}
#[test]
fn state_preserving_move_native_refusal_preserves_tree_frame_range_records_and_recovers(){
 for inert in [false,true]{for profile in 0..4{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,if inert{"var owner=new Document();"}else{"var owner=document;"});run(&mut d,&mut f,&mut p,r#"var root=owner.createElement('div'),left=owner.createElement('div'),right=owner.createElement('div'),text=owner.createTextNode('old');root.append(left,right);left.appendChild(text);var watch=new MutationObserver(function(){});watch.observe(root,{childList:true,subtree:true});var range=owner.createRange();range.setStart(text,1);range.setEnd(text,2);"#);let limit=p.state.retained_limit;let commits=p.state.dom_commits;p.begin_job();match profile{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,_=>p.state.execution_deadline=Some(Instant::now())}assert!(p.runtime.execute("right.moveBefore(text,null)",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).is_err(),"inert={inert} profile={profile}");assert_eq!(p.state.dom_commits,commits);p.state.retained_limit=limit;run(&mut d,&mut f,&mut p,"if(text.parentNode!==left||right.childNodes.length||watch.takeRecords().length||range.startContainer!==text||range.startOffset!==1||range.endContainer!==text||range.endOffset!==2)throw 'native move refusal preserves actual state';right.moveBefore(text,null);if(text.parentNode!==right||watch.takeRecords().length!==2||range.startContainer!==left||range.startOffset!==0)throw 'native move recovery';");}}
}
